/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy.optimize import least_squares
T=np.load('.tmp/tracks.npz');w=T['white'];b=T['black'];V=282;x0=w[0,0];z=lambda x:(x-x0)/(V-x);tt=[np.arange(13),np.arange(17,42),np.arange(49,96)]
def res(p):
 a,u,c,v,d,r=p
 return np.r_[z(w[tt[0],0])-(u*tt[0]-.5*a*tt[0]**2),z(b[tt[1],0])-(c+v*tt[1]-.5*a*tt[1]**2),z(b[tt[2],0])-(d+r*tt[2]+.5*a*tt[2]**2)]
p=least_squares(res,[.0001,.0188,.04,.017,1.3,-.014]).x
print(p,'rmse',np.std(res(p)));a,u,c,v,d,r=p;sb=z(np.mean(b[:12,0])-.22);tc=min(np.roots([-.5*a,v,c-sb]));D=sb-u*tc+.5*a*tc*tc;tr=min(np.roots([-a,v-r,c-d]));sr=c+v*tr-.5*a*tr**2;e=2*(v-a*tc)/(u-a*tc)-1;er=-(r+a*tr)/(v-a*tr)
print('tc,D,rail,e,er',tc,D,sr,e,er)
# counterfactual 1d test
pos=np.array([0.,sb]);vel=np.array([u,0.]);mass=np.array([5.,1.]);dt=1/100;events=[]
for k in range(9501):
 t=k*dt
 if k%500==0:print(round(t,2),np.round(pos,3),np.round(vel,4),'x',np.round((x0+V*pos)/(1+pos),2))
 nv=np.sign(vel)*np.maximum(0,abs(vel)-a*dt);pos+=(vel+nv)*dt*.5;vel=nv
 for j in range(2):
  if pos[j]>sr and vel[j]>0:pos[j]=2*sr-pos[j];vel[j]*=-er;events.append((round(t,2),'rail',j))
  if pos[j]<-.6 and vel[j]<0:pos[j]=-1.2-pos[j];vel[j]*=-er;events.append((round(t,2),'railnear',j))
 if pos[1]-pos[0]<D and vel[0]>vel[1]:
  rel=vel[0]-vel[1];J=(1+e)*rel/(1/mass[0]+1/mass[1]);vel[0]-=J/mass[0];vel[1]+=J/mass[1];over=D-(pos[1]-pos[0]);pos[0]-=over*mass[1]/mass.sum();pos[1]+=over*mass[0]/mass.sum();events.append((round(t,2),'balls'))
print(events)
PY"
